/**
 * Use jsmime to convert _headers to string.
 *
 * @returns {string}
 */
getHeaderString() {
  return jsmime.headeremitter.emitStructuredHeaders(this._headers, {
    useASCII: true,
    sanitizeDate: Services.prefs.getBoolPref(
      "mail.sanitize_date_header",
      false
    ),
  });
}
